customCss:
/* ===== Toads race dossier (scoped via article accent + dossier classes) ===== */
.race-dossier{margin:18px 0 22px;display:flex;flex-direction:column;gap:18px}
.race-dossier-h{margin:0 0 10px;font-size:15px;letter-spacing:.04em;text-transform:uppercase;color:var(--accent2)}
.race-sub-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:12px}
.race-sub-card{display:flex;flex-direction:column;border:1px solid var(--border);border-top:3px solid var(--cap,var(--accent));border-radius:14px;background:linear-gradient(165deg,color-mix(in srgb,var(--cap,var(--accent)) 12%,transparent),transparent 42%),var(--panel2);overflow:hidden;box-shadow:var(--shadow);min-height:100%}
.race-sub-img{height:140px;background:var(--bg2);display:grid;place-items:center;overflow:hidden}
.race-sub-img img{width:100%;height:100%;object-fit:cover;display:block}
.race-sub-fallback{width:100%;height:100%;display:grid;place-items:center;font-size:48px;background:radial-gradient(circle at 50% 30%,color-mix(in srgb,var(--cap) 45%,transparent),transparent 60%),var(--bg2)}
.race-sub-body{padding:12px 12px 14px;display:flex;flex-direction:column;gap:6px}
.race-sub-name{font-weight:900;font-size:15px;color:var(--text)}
.race-sub-aka{font-size:11px;color:var(--muted);font-style:italic}
.race-sub-body p{margin:0;font-size:12.5px;line-height:1.45;color:var(--muted)}
.race-sub-tags{display:flex;flex-wrap:wrap;gap:5px;margin-top:4px}
.race-tag{font-size:10px;font-weight:800;letter-spacing:.04em;text-transform:uppercase;border:1px solid var(--border);border-radius:999px;padding:2px 7px;color:var(--cap,var(--accent2));background:color-mix(in srgb,var(--cap,var(--accent)) 10%,transparent)}
.race-gallery-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(140px,1fr));gap:10px}
.race-gal-item{margin:0;border:1px solid var(--border);border-radius:12px;overflow:hidden;background:var(--bg2)}
.race-gal-item img{width:100%;aspect-ratio:1;object-fit:cover;display:block;background:#1a1028}
.race-gal-item figcaption{padding:7px 8px;font-size:11px;line-height:1.35;color:var(--muted)}
.race-gal-item.broken,.md-figure.broken,.section-figure.broken{opacity:.55}
.race-gal-item.broken figcaption::after,.md-figure.broken figcaption::after{content:" (image missing)";color:var(--danger)}
.md-figure,.section-figure{margin:14px 0;border:1px solid var(--border);border-radius:14px;overflow:hidden;background:var(--panel2);box-shadow:var(--shadow)}
.md-figure img,.section-figure img{width:100%;max-height:380px;object-fit:cover;display:block;background:#140c22}
.md-figure figcaption,.section-figure figcaption{padding:8px 12px;font-size:12px;color:var(--muted)}
.race-thumb.tile{margin:0 0 10px;border-radius:10px;overflow:hidden;border:1px solid var(--border)}
.race-thumb.tile img{width:100%;height:120px;object-fit:cover;display:block}
[data-arttype="races"] .prose h2{border-image:linear-gradient(90deg,var(--art-accent),transparent) 1}
@media(max-width:720px){
  .race-sub-grid{grid-template-columns:1fr 1fr}
  .race-sub-img{height:110px}
}
@media(max-width:480px){
  .race-sub-grid{grid-template-columns:1fr}
}
